static inline int ff4_glyph_index(char c)
{
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return 26 + (c - 'a');
    if (c >= '0' && c <= '9') return 52 + (c - '0');
    if (c == '"') return 65;
    if (c == '\'') return 66;
    if (c == '(') return 67;
    if (c == ')') return 68;
    if (c == '.') return 69;
    if (c == ',') return 70;
    if (c == '-') return 71;
    if (c == '!') return 73;
    if (c == '?') return 74;
    if (c == '%') return 75;
    if (c == '/') return 76;
    if (c == ':') return 77;
    if (c == '&') return 78;
    return -1;
}

